    faq_a_shop_basics: "כשרשימת הקניות ריקה לגמרי – למשל ממש בהתחלה – מופיעה רשימה בסיסית להתחלה: חלב, לחם, ביצים ועוד. נגיעה בפריט מוסיפה אותו לרשימה, ו\"להוסיף את כולם\" מוסיף הכל בבת אחת. ברגע שיש משהו ברשימה – הרשימה הבסיסית נעלמת.",
    faq_q_shop_basics: "מה זו הרשימה הבסיסית ברשימת קניות ריקה?",
    faq_a_nm_me1_guide: "Sky – הדמות שלך ב-New Me, בצורה הראשונה שלו (Sky 1). בפעם הראשונה, מיד אחרי ההצטרפות, נפתח פורטל של אור עם נצנצים מסביב ו-Sky עף ממנו, מסביר בכמה נגיעות מה מחכה, ואז נשאר ליד כל שאלה: בבחירת הארוחות הוא כותב איתך בספר שלו, ונגיעה בעצה שלו מראה עוד אחת. בסוף הוא חוגג איתך ולוקח אותך לסיור קצר – וכשהסיור נגמר, יש לו עוד רגע קטן איתך. אם יוצאים באמצע – של השאלות או של הסיור – בפעם הבאה Sky שמח לראות אותך ושואל אם ממשיכים מאותו מקום.",
    faq_q_nm_me1_guide: "מי מלווה את הכניסה ל-New Me?",
    nm_m1_day_text: "בכל יום – ✓ על כל ארוחה, ואני אספור הכל בשבילך.",
