    nm_m1_skip: "דילוג",
    nm_m1_tip_ai: "מאכל שלא ברשימה? בהמשך, ב\"החלפה\", אפשר לכתוב אותו במילים – וה-AI יחשב אותו. ועכשיו נבחר ביחד מה אוכלים בכל יום.",
    nm_m1_tip_love: "ואם משהו לא אוהבים – תמיד אפשר להחליף ב-AI. לא משנה איזה מאכל – אם אוהבים אותו, הוא נשאר בתפריט.",
