    room_genie_rest: "רוח היער נחה עכשיו – אפשר לחזור אליה מחר ✨",
    faq_a_shop_holidays: "ברשימת הקניות נוגעים במתנה: מופיעים החגים של המדינה שבהגדרות לפי הסדר, עם התאריכים – שמחושבים לבד כל שנה. נגיעה בחג פותחת רשימה מוכנה של מה שקונים לו; הכל מסומן (חוץ ממה שכבר ברשימה), מורידים את מה שלא צריך ונוגעים ב\"להוסיף לרשימה\". שבועיים לפני חג מופיע כרטיס קטן בראש הרשימה; ✕ מסתיר אותו עד החג הבא.",
    faq_q_shop_holidays: "איך עובד \"מה לקנות לחג\"?",
