    shop_hol_added: "נוספו לרשימה: {n}",
    shop_hol_btn: "מה לקנות לחג",
    shop_hol_items_title: "{holiday} – מה לקנות?",
    shop_hol_not_now: "לא עכשיו",
    faq_a_shop_delivery: "ברשימת הקניות נוגעים במשאית: בוחרים מה במשלוח (הכל מסומן), מתי הוא מגיע – היום, מחר או יום אחר – ובאילו שעות (בוקר, צהריים, ערב, או \"אחר…\" לשעות אחרות). הפריטים עוברים לכרטיס \"בדרך\" בראש הרשימה, עם היום והשעות. כשהיום מגיע, \"המשלוח הגיע?\" מופיע ב\"היום שלי\" (ובכרטיס יש \"הגיע?\"). אם הכל הגיע – הם עוברים ל\"קונים שוב\". אם משהו חסר – נוגעים במה שלא הגיע, והוא חוזר ישר לרשימה.",
    faq_a_shop_departments: "הרשימה מסתדרת לבד לפי המחלקות בסופר – פירות וירקות, לחם, חלב וביצים, בשר ודגים, מזווה, קפואים, משקאות, חטיפים, ניקיון, טיפוח, תינוקות וחיות מחמד – כך שעוברים בין המדפים לפי הסדר. המחלקה מזוהה לפי שם הפריט. אם פריט נפל במקום הלא נכון, נוגעים בו ובוחרים לו מחלקה, או \"אחר…\" וכותבים שם משלך.",
    faq_a_shop_share_qty: "כן. ליד כל פריט, + מוסיף עוד אחד (×2, ×3…) ו-− מוריד אחד. כפתור השיתוף בראש רשימת הקניות שולח את כל הרשימה, מסודרת יפה לפי מחלקות, בוואטסאפ, במייל או כהעתקה.",
    faq_a_shop_two_buttons: "שניהם אומרים \"נקנה\". ✕ – למשהו שקונים פעם אחת: הוא יוצא מהרשימה (ומחכה בארכיון 🗑️ למקרה של טעות). ↺ – למה שקונים שוב ושוב: הוא יוצא מהרשימה ומחכה ב\"קונים שוב\" – הכפתור הקטן ↺ ליד הפח בתחתית הרשימה פותח אותו, ונגיעה אחת שם מחזירה פריט לרשימה. ב\"עריכה\" שבתוכו אפשר להוציא ממנו פריט. כשמוסיפים פריט, מה שכבר קנו פעם מופיע כהצעה, ואם הוא כבר ברשימה – הוא פשוט נהיה ×2 ולא שורה נוספת.",
