    nm_swap_time: "שעה",
    faq_a_new_me_challenge_journal: "כשאתגר מסתיים – גדול, מיני או אתגר השבוע – בחגיגה יש כפתור 📝 איך עבר?. הוא פותח דף ביומן האתגרים: איך זה הרגיש (חמישה פרצופים), מה עזר, מה היה קשה ומה לוקחים מזה הלאה – שום דבר לא חובה, ואפשר גם אחר כך. היומן הוא יהלום בתיק הקסום: כל אתגר שהסתיים, עם התאריך ומה שנכתב, האחרון למעלה – נגיעה פותחת אותו לקריאה, לעריכה או לשיתוף (משתפים רק את מה שבדף). אתגר שהסתיים מקבל גם מדליה בהישגים, תחת ״אתגרים שהשלמתי״. יומן האתגרים נפרד מהיומן הרגיל.",
