    faq_a_ai_reminder_in_text: "כן – כותבים אותה יחד עם המשימה, למשל ״מחר ב-17:00 לאסוף חבילה, עם התראה שעה לפני״. התזכורת נשמרת על המשימה עצמה: שעה לפני, חצי שעה, יום לפני וכן הלאה, ו״תזכיר לי״ בלי זמן זה 10 דקות לפני. תזכורת שנכתבה בטקסט קודמת לשדה התזכורת שבאותו חלון.",
