    books_home_q: "באיזה עמוד אני?",
    books_home_save: "לשמור",
    faq_a_books_home_chip: "כן. בפינת הקריאה, בכרטיס של ספר שקוראים עכשיו, נוגעים ב-📌 במסך הבית. במסך הבית, מתחת לברכה, מופיע כפתור קטן עם הספר והעמוד – נוגעים, כותבים את מספר העמוד החדש ושומרים, וההתקדמות נרשמת (גם בפינת הקריאה). נגיעה נוספת ב-📌 מורידה אותו. אפשר כמה ספרים יחד – כפתור לכל אחד – ואותו דבר בכל המכשירים.",
    faq_a_room_genie: "במרפסת מול הים, נגיעה במנורת אלאדין מוציאה את רוח היער – ומתחילה שיחה: מה המשאלה (מה רוצים לשנות בחיים), איך זה ירגיש כשזה יתגשם, מה קשה בדרך, ואיך אפשר לנצל את המצב של עכשיו לטובה. אחר כך כמה זמן זה ייקח בערך, צעד ראשון קטן ועוד שניים, ו״אם… אז…״ לרגעים שבהם יהיה קשה. בסוף מופיעה כל המשאלה צעד אחר צעד, ואפשר להפוך אותה ליעד ב״היעדים שלי״ (הצעדים הופכים לתחנות בשביל, עם תאריך לפי הזמן שנבחר; שם אפשר לשנות הכל) או לשמור ביומן – ואז הרוח נפרדת. כלום לא נשמר אם לא בוחרים באחד מהם. מהפעם השנייה הרוח שואלת קודם אם רוצים לשנות עוד משהו בחיים: כן – אותה שיחה; לא כרגע – תזכורת להגשים את היעדים שכבר הוצבו. הרוח יוצאת פעם ביום: אחרי שמשאלה נשמרה (או אחרי ״לא כרגע״), היא נחה עד מחר. השאלות בנויות לפי דרך מוכרת להפוך משאלה לתוכנית: משאלה, תוצאה, מכשול ותוכנית.",
    faq_q_books_home_chip: "אפשר לראות את הספר והעמוד במסך הבית?",
