    room_genie_turn_ex: "למשל: קשה לגור בבית – אבל גם בחוץ יהיה קשה. אז מה הבית נותן עכשיו, שאפשר להשתמש בו?",
    room_genie_turn_q: "לפעמים דווקא מה שקשה הוא גם ההזדמנות. איך אפשר לנצל את המצב של עכשיו לטובה?",
    faq_a_new_me_week_challenge: "אתגר קטן לשבוע אחד, שבוחרים בעצמנו. במסדרון יש כרטיס גדול: ״על מה רוצים לעבוד השבוע?״ – נוגעים, בוחרים תחום (עם עצמי, עם אחרים, ללמוד ולגדול, רוגע, צעדים קטנים של אומץ, בית ושגרה) ואתגר, ובוחרים מתי מתחילים. אותם אתגרים נמצאים גם במסך האתגרים, תחת 🌱 התפתחות אישית. כל יום מסמנים ✓ בכרטיס (יום חופשי אחד בשבוע), וכל שבוע שמסתיים מביא מפתח חדש לעולם הסודי. ״לקרוא 2 עמודים ביום״ מסומן לבד מהעמודים שנרשמים בפינת הקריאה. כשהשבוע מסתיים, 📌 להשאיר כמשימה יומית מוסיף אותו ל״השגרה שלי״ בשעה שבוחרים, עם ✓ כל יום. רץ אתגר שבוע אחד בכל פעם; האתגרים הגדולים והקטנים ממשיכים לצידו.",
    faq_q_new_me_week_challenge: "מה זה אתגר השבוע?",
