    faq_a_new_me_game: "ב-New Me כפתורי המשחק נשארים תמיד באותו מקום – במסדרון, בחדר הסודי ובכל מקום ביער; רק הציור שבאמצע מתחלף. למעלה: היום במסע, המפתחות, הרצף והאנרגיה של היום (כמה נאכל מתוך התוכנית), ומתחת – המשימה הבאה: הארוחה הבאה בשעה שלה (נגיעה פותחת אותה, עם ✓ אכלתי). בצד: כל היום, אתגרים והמסע שלי, ולידם אתגר השבוע – 7 הימים שלו ו-✓ להיום. למטה: התיק הקסום (כל מה שיש ב-New Me – מפת העולם, המסע שלי, קניות, הישגים, יומן אתגרים, מדידות, תמונות, לוח חודשי, טבלה יומית, תזכורות, תפריט PDF והגדרות; הוא נפתח כמסך משלו). במפת העולם, הראשונה בתיק, רואים את כל המקומות ביער – נוגעים במקום והולכים אליו; במקום נעול כתוב כמה מפתחות צריך. Sky הוא הדמות שלך על השביל ביער: הוא מתחיל כ-Sky 1, אחרי כמה אתגרים (4 מפתחות) גדל ל-Sky 2, ולקראת הסוף (9 מפתחות) ל-Sky 3 – ורואים את המהפך קורה. נגיעה ב-Sky מראה את כל השלבים – אפשר לבחור שוב כל שלב שכבר הגיעו אליו, כך שגם צורה קודמת יכולה לחזור. Sky מרחף – גוררים אותו באצבע או בעכבר, והכניסה שהוא נוגע בה נפתחת (בנעולה כתוב כמה מפתחות חסרים). Sky בא גם לכל חדר ולכל מקום, ומרחף איפה שמשאירים אותו: גוררים אותו לכל מקום, וגוררים את הטבעת הזוהרת שמתחתיו כדי לסובב אותו סביב עצמו; הוא פונה לכיוון שאליו הוא זז (במחשב: החיצים מזיזים, Q ו-E מסובבים). במסדרון, ה-🏠 הקטן מתחת לפס העליון חוזר למסך הבית; בכל חדר ובכל מקום, הכפתור שבאותה פינה חוזר למסדרון.",
    faq_q_new_me_game: "איך עובדים כפתורי המשחק, מפת העולם ו-Sky?",
