    faq_a_new_me_menu_build: "קודם השאלון שואל אילו ארוחות אוכלים ומתי (2 ארוחות + נשנוש, 2 ארוחות + ארוחת ערב קלה, או שתיהן), ואם יש משהו בערב – לאכול או לשתות, מה ובאיזו שעה. ב\"2 ארוחות + נשנוש\" הארוחות הן ארוחת צהריים (11:30) וארוחת ערב (19:00), והנשנוש ב-16:00. אחר כך מופיעות כל האפשרויות של הארוחות האלה. בוחרים עד 2 אהובות בכל ארוחה – בתפריט כתוב \"זה או זה\". בחלק מהאפשרויות (פיתה וממרח, קורנפלקס וחלב, משהו קל) בוחרים עד 3 דברים שאוהבים, כל אחד במנה שלו, ובתפריט כתוב \"זה או זה או זה\"; הקלוריות לפי מה שנבחר. כך גם בקפה ובשתייה. כל בחירה מאוזנת, כך שהיום מסתכם בדיוק ל-1,300 או ל-1,500. כדי לשנות בכל רגע: ⚙️ הגדרות ← 🍽️ בניית התפריט, או \"בוחרים עד 3 שאוהבים\" בכרטיס של הארוחה.",
