    faq_a_myday_water_toggle: "כן. כוס המים ב'היום שלי' (עם + לעוד כוס) מופיעה כברירת מחדל. כדי להסתיר אותה מכבים את \"הצגת המים ב'היום שלי'\" בהגדרות > התאמה אישית ויומן. שום דבר לא נמחק – מעקב המים ממשיך לעבוד, והדלקה מחדש מחזירה את הכוס.",
