    myday_water_toggle_label: "הצגת המים ב'היום שלי'",
    faq_a_routine_newme_sync: "למי שיש New Me, ב-⚙️ של 'השגרה שלי' יש מתג 'סנכרון עם New Me'. כשהוא דלוק (ברירת המחדל), הארוחות של New Me מופיעות ב'היום שלי' וב'השגרה שלי' – במקום ארוחות השגרה שהוסתרו. כשהוא כבוי, הארוחות של New Me יוצאות משם והשגרה חוזרת בדיוק כמו שהייתה. כלום לא נמחק – הדלקה מחדש מחזירה הכול ושואלת אילו ארוחות בשגרה להסתיר.",
    faq_q_routine_newme_sync: "איך מדליקים או מכבים את הסנכרון של New Me עם השגרה ו'היום שלי'?",
