    theme_name_watercolor_wash: "צבעי מים",
    faq_a_food_list_languages: "רשימת המאכלים המובנית נבנתה עם מאכלים ושמות ישראליים. בעברית מופיעה כל הרשימה; בשאר השפות כל מאכל מוצג בשמו האנגלי, והחיפוש מוצא כל שם אנגלי שהוא מכיר (למשל 'broth' מוצא מרק צח), ומאכלים שיש להם רק שם עברי לא מופיעים שם. כל מה שלא ברשימה אפשר פשוט לכתוב במילים – הערכת ה-AI עובדת בכל שפה.",
    faq_q_food_list_languages: "למה ברשימת המאכלים יש שמות באנגלית, ופחות מאכלים, בשפות אחרות?",
    settings_copyright_line: "© 2026 כל הזכויות שמורות. האפליקציה פותחה על ידי eden zabari.",
    workout_ready_replace_btn: "החלפה",
    faq_a_sport_workout_ai: "ב\"האימונים שלי\" ← ⋯ ← \"תוכנית עם AI\" (וכשהטבלה ריקה – גם באריח שליד התוכניות המוכנות). עונים בכמה נגיעות: כמה פעמים בשבוע, מתי, מקום, רמה ומטרה – ברובן יש גם \"אחר\" – ואפשר להוסיף שורה חופשית, למשל ברך רגישה או ריצת 5 ק״מ עד הקיץ. ה-AI בונה שבוע שלם: סוגי אימונים, ימים, שעות, משך, עצימות, תרגילים וימי מנוחה. לפני ששום דבר נשמר מופיעה תצוגה מקדימה: \"להכניס לטבלה\" (במקום הטבלה או בנוסף לה), \"הצעה אחרת\" (עד 3 פעמים) או \"לשנות תשובות\". התוכנית מתונה בכוונה, וכשמזכירים כאב או פציעה מגיעות הצעות עדינות והמלצה להתייעץ עם איש מקצוע. זה חלק ממכסת ה-AI של הלו״ז והשגרה: 5 פעמים חינם, ו-60 בחודש בפרימיום.",
    faq_q_sport_workout_ai: "איך בונים תוכנית אימונים עם AI?",
