    workout_ai_working: "התוכנית בדרך…",
    faq_a_sport_workout_jar: "לכל סוג אימון יש כוכב בצבע משלו – ריצה ורוד, הליכה ירוק, שחייה כחול וכן הלאה. כל אימון שנרשם השבוע, מהטבלה או בנפרד, מפיל את הכוכב שלו לצנצנת שלמעלה ב\"האימונים שלי\", והצנצנת מתמלאת עד המטרה השבועית (נגיעה בה משנה את המטרה). כשמגיעים למטרה הצנצנת זוהרת, והצנצנת הקטנה שלידה סופרת כמה שבועות ברצף היא התמלאה.",
    faq_q_sport_workout_jar: "מה הכוכבים הצבעוניים והצנצנת ב\"האימונים שלי\"?",
    faq_a_sport_workout_gcal: "כן – ב-⋯ ← Google Calendar (אחרי שמחברים את Google Calendar בהגדרות). כל אימון עם שעה הופך לאירוע שחוזר כל שבוע בימים שלו, ושינויים באפליקציה מתעדכנים בו. התזכורות מגיעות רק מהאפליקציה, אז גוגל לא מוסיפה תזכורות משלה, והאימונים לא מופיעים פעמיים באפליקציה. נגיעה נוספת מסירה מ-Google Calendar רק את האימונים.",
    faq_q_sport_workout_gcal: "האימונים יכולים להופיע ב-Google Calendar?",
    workout_gcal_btn: "Google Calendar",
    workout_gcal_error: "לא הצלחנו לעדכן את Google Calendar – ננסה שוב בשינוי הבא",
    workout_gcal_not_connected: "קודם מחברים את Google Calendar בהגדרות",
    workout_gcal_off_toast: "האימונים הוסרו מ-Google Calendar",
    workout_gcal_on_toast: "האימונים נכנסו ל-Google Calendar",
    faq_a_sport_workout_reminder: "כן – באימון, תזכורת: 10 דקות, 30 דקות או שעה לפני, או זמן אחר (לאימון צריכה להיות שעה). היא מצלצלת כמו שאר התזכורות, פעם אחת ובמקום אחד: באפליקציה אם היא פתוחה, אחרת בטלפון. \"בוצע\" רושם את האימון בהיסטוריה, ו\"עוד לא\" מזכיר שוב בעוד 5 דקות.",
    faq_q_sport_workout_reminder: "אפשר לקבל תזכורת לפני אימון?",
    workout_reminder_30min: "30 דקות לפני",
    workout_reminder_label: "תזכורת",
    workout_reminder_need_time: "כדי לקבל תזכורת צריך שעה",
    faq_a_sport_workout_share: "ב-⋯ ← שיתוף השבוע הופך לתמונה זכוכיתית בצבעי הערכה, עם קישור עדין לאפליקציה (בטלפון – ישר לחלון השיתוף, במחשב התמונה נשמרת). ⋯ ← PDF להדפסה פותח דף נקי של כל השבוע, עם ריבוע לסימון ליד כל אימון ותרגיל – בוחרים \"שמירה כ-PDF\" או מדפיסים. הטבלה מופיעה גם בדוח הנתונים בהגדרות, בחלק של הספורט.",
    faq_q_sport_workout_share: "איך משתפים או מדפיסים את השבוע באימונים?",
    share_image_saved: "התמונה נשמרה – אפשר לצרף אותה",
    share_save_image: "שמירת התמונה",
    workout_pdf_btn: "PDF להדפסה",
    workout_share_btn: "שיתוף",
    faq_a_sport_workout_board: "ב-⋯ ← לוח שבועי כל יום הוא עמודה: גוררים אימון ליום אחר (בטלפון – לחיצה ארוכה ואז גרירה). באימון, \"גם בשגרה שלי\" מכניס אותו לשגרה בשעה ובימים שלו, ושינויים מסתנכרנים בשני הכיוונים; ומפריט בשגרה, \"להוסיף לטבלת האימונים\" עושה את ההפך. ✓ באחד מהם נספר בשניהם, ובהיום שלי הוא מופיע פעם אחת – בצ'יפ ליד המים.",
    faq_q_sport_workout_board: "איך מעבירים אימון ליום אחר, ומחברים אותו לשגרה?",
    routine_in_workouts_btn: "פתיחה בטבלת האימונים",
