    routine_to_workout_done: "נוסף לטבלת האימונים 💪",
    workout_delete_confirm_routine: "האימון יימחק מהטבלה ומהשגרה. אימונים שכבר נרשמו בהיסטוריה נשארים.",
    workout_moved: "האימון עבר ל{day}",
    workout_routine_need_time: "כדי להוסיף לשגרה צריך שעה",
    workout_routine_toggle: "גם בשגרה שלי",
    workout_view_board: "לוח שבועי",
    workout_view_timeline: "ציר זמן",
    faq_a_sport_workout_plan: "במעקב אימונים, ב\"האימונים שלי\": + אימון – סוג, ימים, שעה, משך, עצימות ומקום (וגם \"אחר\"). באימוני כוח, פונקציונלי ושחייה אפשר להוסיף רשימת תרגילים, ו\"מנוחה\" מסמנת יום מנוחה. אפשר גם להתחיל מתוכנית מוכנה. האימון של היום מופיע בגדול וכל השבוע מתחתיו; ✓ רושם אותו בהיסטוריית האימונים יחד עם העצימות. ב-⋯ קובעים מטרה שבועית (אימונים או דקות) – וכל אימון שנעשה מכניס את הכוכב שלו לצנצנת.",
    faq_a_sport_workout_today: "בהיום שלי, ליד המים, צ'יפ קטן מראה את האימון של היום – נגיעה פותחת את הפרטים, ✓ ו-▶. ▶ מתחיל טיימר שממשיך לרוץ בצ'יפ במסך הבית, ו\"סיום\" רושם את האימון עם הזמן האמיתי. אם האתגר \"שבועיים של תנועה\" ב-New Me פעיל, אימון שנרשם נספר בו לבד.",
    faq_q_sport_workout_plan: "איך בונים טבלת אימונים?",
