    faq_a_new_me_magic_themes: "חמש ערכות נושא מנצנצות שכלולות ב-New Me: יער קסום, אבק כוכבים, פיית ורדים, זוהר קסום ושקיעת זהב. בוחרים אחת בתוך New Me (⚙️ הגדרות > צבעים) או בהגדרות > מראה ותצוגה, ומברשת של נצנצים צובעת את המסך בערכה שנבחרה. בערכה קסומה יש נצנצים בכל האפליקציה וגם בכל נגיעה. אפשר לחזור לכל ערכה אחרת בכל רגע.",
