    apptour_focus_text: "הכול זז הצידה חוץ מהדבר האחד של עכשיו – עם ✓ גדול. אחריו מופיע הבא בתור.",
    apptour_m_presets_text: "הארוחות הקבועות במקום אחד: חיפוש, לאחרונה ולפי שעה ביום – ו-＋ מוסיף ארוחה להיום.",
    apptour_night_text: "🌙 מחשיך את כל האפליקציה, ו-☀️ מחזיר את היום.",
    apptour_noteline_text: "כותבים ולוחצים ➤ – זה נשמר בפתקים. 📝 בתחילת השורה מחליף ל-🛒 קניות או ל-🍎 ארוחה קבועה.",
    apptour_search_text: "פתקים, קניות, יומן, מתכונים, מחברות, יעדים, טבלאות וספרים – חיפוש אחד מוצא הכול.",
    faq_a_new_me_ai_menu: "לפני התפריט השאלון שואל אילו ארוחות אוכלים ומתי (2 ארוחות + נשנוש, 2 ארוחות + ארוחת ערב קלה, או שתיהן), אם יש משהו קטן בערב ובאיזו שעה, מה לא אוכלים, ואיך שותים קפה או תה. אז ה-AI בונה 3 אפשרויות לכל ארוחה – כל אחת בגודל החלק שלה מהיום, כך שהיום עדיין מסתכם בדיוק ל-1,300 או ל-1,500 – ורעיונות לשתייה, שנשמרים כמשקאות הקבועים. בוחרים עד 2 אהובות בכל ארוחה; האפשרויות המקוריות נמצאות ממש מתחתן, וב-🔄 החלפה הן מופיעות אחרי התפריט האישי. 🔄 אפשרויות אחרות בונה סבב חדש (3 פעמים בכל שאלון). כדי לשנות תשובות או לבנות תפריט חדש בכל רגע: ⚙️ הגדרות ← ✨ תפריט אישי (AI).",
