    faq_a_new_me_day_total: "כל יום מסתכם בדיוק לתוכנית: הארוחות, כ-150 קלוריות לקפה ולשתייה במשך היום, ומה שנבחר לערב – משהו קטן לאכול או משהו לשתות. לערב בוחרים עד 3 שאוהבים (למשל בננה, יוגורט או 2 קוביות שוקולד מריר; או תה צמחים, תה עם מעט חלב או חלב חם), והקלוריות שלהם יורדות מהארוחות. כל בחירה מתאזנת לבד: אפשרות קטנה או גדולה יותר, ארוחה שירדה, ארוחת הבוקר הקטנה והארוחה הקטנה שמגיעה איתה, או הערב – ההפרש נוסף לארוחות או יורד מהן, לכל אחת לפי הגודל שלה, ומתחת לכל ארוחה כתוב כמה (+ או −) ומה אפשר להוסיף או להוריד. ארוחה שכבר סומנה נשארת כמו שנרשמה. בשאלון, ליד כל ארוחה מופיע התיקון שלה, וקופסה קטנה מראה ארוחות, שתייה, ערב והסה״כ. מתחשק משהו אחר באותו יום? חשוב שהסך הכול יישאר באותה כמות קלוריות או פחות.",
    faq_q_new_me_day_total: "איך היום של New Me מסתכם בדיוק ל-1,300 / 1,500, ואיפה השתייה נכנסת?",
