    books_quotes_chip: "ציטוטים",
    faq_a_book_quotes: "במדף בחדר הסודי (ציטוטים), או בצ'יפ הקטן 💬 ציטוטים בפינת הקריאה – זו אותה רשימה. לוחצים על \"+ ציטוט\", כותבים את המשפט ובוחרים את הספר מפינת הקריאה, או מקלידים ספר אחר ב\"✏️ אחר\"; הסופר/ת לא חובה. ✏️ עורך ציטוט ו-🗑️ מוחק. הציטוטים הם סימניות שמחליקים ביניהן – 🎨 למעלה מחליף לתמונות או לקיר של כרטיסים.",
    faq_a_room_wish_jar: "במדף בחדר הסודי יש צנצנת זכוכית לחלומות. לוחצים על הצנצנת הקטנה במדף העליון (או המדף > צנצנת המשאלות) וכותבים איך רוצים שהחיים ייראו – הכי פרוע שאפשר, בלי נכון ולא נכון. כל משאלה מתקפלת לפתק ונופלת לצנצנת. \"לשלוף פתק\" פותח פתק אקראי, ואפשר גם לפתוח כל פתק בעצמו. מהפעם השנייה שפותחים את אותה משאלה, אפשר להפוך אותה ליעד ולפרק לצעדים קטנים. פעם בשבוע קופץ פתק עדין עם אחת המשאלות – בלי לחץ, רק תזכורת לאן מכוונים.",
