    faq_a_saved_meals_page: "לארוחות הקבועות יש דף משלהן: תזונה ומדדים > ⭐ ארוחות קבועות (או ⭐ בתפריט). החיפוש למעלה מוצא ארוחה לפי שם או מצרך, \"לאחרונה\" מראה את מה שנוסף לאחרונה, והלשוניות (בוקר, צהריים, ערב, מרקים…) מראות כל זמן ביום. \"+ להיום\" מוסיף ארוחה למעקב הארוחות היומי, במשבצת הפנויה הבאה. לחיצה על ארוחה פותחת עריכה ומחיקה, ו־＋ למעלה מוסיף ארוחה חדשה.",
