    presets_tab_soup: "מרקים",
    presets_tab_sweet: "מתוקים",
    faq_a_notes_sticky_look: "הפתקים הם רשימה קצרה של כרטיסי זכוכית – 🎨 בראש הפתקים מחליף את הנראות של כל הפתקים: הרשימה, כפתורי הימים שלמעלה והחלון שבו כותבים פתק – זכוכית, רשימה נקייה, כרטיסיות או סלוטייפ. פתק שגוררים נשאר בדיוק בנראות ובצבע שלו. לחיצה על הטקסט פותחת פתק – שם אפשר לערוך, לשנות צבעים ולראות מתי נכתב לאחרונה. לוחצים על ○ כשהפתק בוצע, ו-× מעביר אותו לארכיון (🗑️ בתחתית הרשימה מחזיר). גוררים ב-⠿ כדי לשנות סדר, אל מתחת ל\"להגיע לזה\", או אל יום למעלה. ! מסמן פתק כדחוף – הוא עולה בעדינות לשורות הראשונות, עם תג קטן ״דחוף״; נגיעה נוספת מורידה את הסימון.",
    faq_q_notes_sticky_look: "איך פותחים, עורכים או מוחקים פתק?",
    note_to_archive_btn: "העברה לארכיון",
    faq_a_routine_clash: "אם באותה שעה כבר יש פריט באותם ימים, יש שתי אפשרויות: \"להחליף\" – הפריט החדש נכנס לשעה הזו ובוחרים לאיזו שעה להעביר את הפריט הקודם (כשעורכים פריט קיים, מוצעת השעה הקודמת שלו, כך ששניהם פשוט מתחלפים), או \"גם וגם\" – שניהם נשארים באותה שעה, אחד מתחת לשני. אם הימים שונים (למשל אחד בא׳–ה׳ והשני בשישי), לא שואלים בכלל.",
