    routine_clash_title: "בשעה {time} כבר יש: {title}",
    faq_a_new_me_coffee: "מתחת לתפריט של היום יש סיכום קצר: כמה קלוריות כל הארוחות של היום, כמה נשאר לקפה ולשתייה, וכפתורים של הקפה והשתייה שנבחרו – לחיצה אחת מוסיפה לשתייה. ב\"בוחרים עד 3 שאוהבים\" שמתחת לכפתורים (וגם בשאלון) בוחרים מה מופיע: מים / סודה, תה צמחים, משקה דיאט, שחור / אמריקנו (~5), תה עם מעט חלב (~25), קפה על בסיס מים עם עד 100 מ״ל חלב או תחליף חלב (~50), שוקו קל, חלב חם או קפה רגיל / הפוך (~120).",
