    nm_late_room_line: "משהו קטן לפני השינה · נשארו ~{n} קק״ל להיום",
    faq_a_recipe_examples: "מתחת למתכונים שלך יש מתכונים לדוגמה: ארוחות בוקר, סלטים, מרקים, עיקריות, תוספות, נשנושים, קינוחים ומנות טבעוניות. בכל אחד יש זמן הכנה, קלוריות למנה וכמה גרם שוקלת מנה אחת. לוחצים על מתכון כדי לפתוח אותו, ו\"לשמור במתכונים שלי\" יוצר עותק שאפשר לערוך. התוויות של הקטגוריות מסננות, ולחיצה נוספת על אותה תווית מחזירה הכל.",
    faq_a_recipe_grams: "בתוך מתכון, ליד הקלוריות, כתוב \"מנה ≈ X גרם\". במתכונים שלך ממלאים \"גרם למנה\" (ואם רוצים גם זמן הכנה) בטופס המתכון. שניהם לא חובה, והזמן מופיע בפס הצבע של המתכון.",
