    recipes_examples_title: "מתכונים לדוגמה",
    faq_a_recipe_scan_multi: "כן. ב\"הוספת מתכון\" לוחצים על 📷 ובוחרים תמונה אחת או כמה (עד 6, אפשר גם PDF). כל אחת מופיעה ברשימה קצרה, ובוחרים מה יש בה: הכל, מצרכים או הכנה. \"➕ עוד תמונה\" מוסיף עוד. אחר כך לוחצים \"✨ לסרוק את המתכון\": ה-AI מחבר הכל למתכון אחד, לפי הסדר ובלי שורות כפולות, וזה נספר כסריקה אחת. גם כמה תמונות שנבחרות מ-📷 תמונה בעוזר ה-AI נפתחות כאן.",
    faq_q_recipe_scan_multi: "אפשר לסרוק מתכון אחד מכמה תמונות, למשל המצרכים לחוד ואופן ההכנה לחוד, או שני דפים?",
