    faq_a_note_written_at: "לוחצים על הטקסט של הפתק כדי לפתוח אותו. בפנים, מתחת לטקסט, כתוב מתי הוא נכתב לאחרונה, עם תאריך ושעה מדויקים. רק שינוי בטקסט עצמו מעדכן את זה: ארכיון ושחזור, סימון ✓, צבעים או הזזה של הפתק לא משנים אותו.",
