    faq_a_new_me_small_breakfast: "ארוחת בוקר קלה (כ-170 קלוריות): פיתת כוסמין (עד 100 קלוריות) עם ממרח או גבינה, ועוד ירק – בוחרים עד 3 שאוהבים, למשל כפית ממרח שוקולד, כפית חמאת בוטנים או פרוסת גבינה צהובה (עד 22%). כי היא קטנה, מגיעה איתה \"ועוד ארוחה קטנה\" בשעה אחרת (שעה וחצי אחריה, למשל 11:30 ← 13:00 – ואפשר לבחור שעה אחרת): עוד פיתה וממרח, יוגורט חלבון ופרי, פריכיות וגבינה, דגנים וחלב או חצי פיתה וביצים – עד כ-200 קלוריות, עם ✓ משלה. מה שעוד נשאר מתחלק בין שאר הארוחות, וכל ארוחה מראה כמה נוסף לה, כך שסך היום נשאר כמו בתוכנית. אפשר לבחור אותה בשאלון, או להחליף אליה רק להיום ב-🔄 – למשל כשאוכלים מאוחר.",
