    faq_a_ai_icon: "כן – בהגדרות > מראה ותצוגה. הבועה הרכה היא ברירת המחדל, ובפרימיום אפשר לבחור גם מוח צף או רובוט.",
    faq_a_new_me_favorites: "כן. בשאלון (וגם במילוי מחדש מההגדרות) אפשר לבחור עד 2 אפשרויות לכל ארוחה. הראשונה מופיעה בתפריט, ומתחתיה שורת \"או\" עם השנייה – נגיעה בה מחליפה אליה להיום בלבד. ואם ארוחת הבוקר לא נאכלה בזמן, \"⏰ אחר כך\" מעביר אותה להמשך היום, בלי לשנות את הקלוריות.",
    faq_a_theme_mode: "חלק מהערכות המיוחדות נראות הכי יפה בכהה – צבעי מים, זוהר צפוני, ברבי ושתי ערכות הנצנצים – אז בחירה באחת מהן מעבירה את האפליקציה למצב כהה, ובחירה בכל ערכה אחרת (גם החללית) מעבירה לבהיר. שחור ואפור כהה נשארים כהים. תמיד אפשר לשנות אחר כך ב-🌙 בתפריט או ב\"מצב בהיר\" בהגדרות.",
    faq_a_water_month: "במעקב המים. ליד כל רישום ביומן של היום כתובה השעה שבה נרשם, ו\"טבלה חודשית\" פותחת את כל החודש: בכל יום כתוב כמה ליטרים נשתו (✓ כשהגיעו ליעד היומי), ונגיעה ביום מציגה את הרישומים שלו עם השעות.",
