    room_reveal_star: "כוכב חדש נדלק בטלסקופ שעל הגג ✨",
    faq_a_room_records: "הפטיפון עומד בחדר מההתחלה, על הגדם שליד הכורסה. התקליטים שלו פותחים ביוטיוב את הקליפים הרשמיים של להיטים גדולים מהשנים האחרונות, ומתחתם יש חמישה לחנים שקטים שמתנגנים כאן בחדר – התקליט מסתובב בזמן שהם מתנגנים, ו-\"⏹ לעצור\" מפסיק את המוזיקה.",
    faq_a_room_roof_gifts: "הם מגיעים עם המפתח ה-8. נגיעה בטלסקופ מאפשרת להסתכל דרכו: שמי הלילה מקרוב – גוררים (או בחצים) כדי להסתכל מסביב – והאתגרים שהסתיימו מציירים בהם קבוצת כוכבים, כוכב לכל אתגר; נגיעה בכוכב מראה איזה אתגר זה היה. נגיעה בתיבה הקטנה פותחת אותה – בינתיים היא ריקה – ונגיעה נוספת סוגרת.",
