    faq_a_new_me_preview: "כן. עמוד New Me נפתח בסרטון קצר של מה שקורה בפנים: השאלון, המנורות במסדרון, התרמיל, האתגרים והמפתחות. מתחתיו יש את כל מה שכלול, הצצה ליום אחד ותשובות קצרות.",
