    ai_chat_food_updated: "עודכן:",
    faq_a_ai_chat_food_fix: "כן. מתחת לתשובה בשיחה נוגעים ב-✏️ לתקן קלוריות / חלבון, משנים את המספרים ושומרים. משתנה רק מה שנוסף עכשיו – גם אם הוא צורף לנשנוש שכבר היה. AI עלול לטעות, אז כדאי לבדוק.",
    faq_a_new_me_home_btn: "למי שיש New Me, 💎 קטן ליד מצב הפוקוס בראש מסך הבית פותח את התפריט של היום. הארוחות של היום מופיעות גם ב'היום שלי', כל אחת עם ✓.",
    faq_a_routine_item_days: "כן. נוגעים בפריט ב'השגרה שלי' ובוחרים את הימים שלו תחת 📅 ימים – למשל מסחר רק משני עד שישי, גם כשהטאב הוא של ראשון עד שישי. בשאר הימים הוא לא מופיע ב'היום שלי' ואין לו ✓, וב'השגרה שלי' הוא נשאר, חלש יותר, עם הימים שלו לידו. הכרטיס ששואל על פריט אחרי 3 ימים בלי ✓ סופר רק את הימים של הפריט.",
