    routine_item_days_label: "📅 ימים",
    home_note_meal_ph: "חיפוש ארוחה קבועה…",
    menu_quick_search: "חיפוש מהיר",
    nm_times_hint: "טיפ: אפשר לשים את השעה הכי מאוחרת שבה אוכלים כל ארוחה – למשל 9:00 אם בדרך כלל אוכלים בסביבות 8.",
    room_game_marquee: "בדרך – עוצרים ליהנות",
    room_sand_erase_aria: "לשפשף כדי למחוק את הכתוב",
    faq_a_home_note_line: "כותבים בשורה שבאמצע מסך הבית ולוחצים ➤ (או Enter) – וזה נשמר בפתקים. לחיצה על 📝 בתחילת השורה מחליפה אותו ל-🛒, ואז מה שנכתב נכנס לרשימת הקניות. לחיצה נוספת – 🍎: מקלידים כמה אותיות, הארוחות השמורות שמתאימות עולות, ונגיעה באחת רושמת אותה בארוחות של היום. ב-🎤 אפשר פשוט להגיד את זה בקול.",
    faq_a_night_mode: "פותחים את התפריט ☰ ולוחצים על 🌙 למעלה – כל האפליקציה עוברת לכהה. ☀️ באותו מקום מחזיר את היום. זה נמצא גם בהגדרות, תחת \"מצב בהיר\".",
    faq_q_home_note_line: "איך רושמים פתק מהיר ממסך הבית?",
    faq_q_night_mode: "איך עוברים למצב לילה?",
    menu_day_mode: "מצב יום",
    menu_night_mode: "מצב לילה",
    faq_a_secret_room_yoga: "בסוף השביל ביער יש שער זוהר, ומאחוריו, ליד מפל, יצורי היער – לומי, פופי, ניקסי וספארקלט – יושבים על המזרונים בחצי עיגול, ופלאורה, מורת היוגה, יושבת מולם על המזרון הבודד שעל הסלע. נוגעים בפלאורה: היא פותחת את העיניים, הכול מתקרב, והשיחה מתחילה לאט, עם זמן לקרוא – פלאורה שואלת מה שלום כולם, כל יצור עונה בשם שלו (וליד כל שורה יש ציור קטן של מי שמדבר), ואז היא שואלת איך מרגישים עם האנשים הקרובים. השיחה ממשיכה לפי התשובות – אנשים טובים, מישהו שקשה איתו, או קצת לבד. כל דרך נגמרת במשימה קטנה (אפשר להוסיף אותה ישר ל\"היום שלי\"; כשהמשימה היא לכתוב משהו – יש מקום לכתוב, והכתוב נשמר ביומן הקסום) ובתנוחה עם שלוש נשימות ביחד. ↩ חוזר צעד אחורה, ו-✦ מתחיל שיחה חדשה. המפתח הבא פותח את המפל: ישיבה על האבן מעלימה את הכול, ונשאר רק קול המים. מתכופפים מעל הבריכה ושאלה עולה מהמים – מה האני האמיתי היה עושה היום? – והתשובה נכנסת ל\"היום שלי\" כמשימה קטנה. זה רגע נעים, לא תחליף לשיחה עם איש מקצוע.",
    faq_q_secret_room_yoga: "מה קורה ביוגה ביער?",
