    nm_time_hour: "שעה",
    nm_time_minutes: "דקות",
    routine_time_taken: "בשעה הזו כבר יש משהו: {title}",
    faq_a_new_me_times: "בשאלון בהתחלה, ובכל זמן בהגדרות של New Me ← \"שעות האוכל\". אם בשגרה כבר יש שעות לארוחות, השעות נלקחות משם – ואפשר להסתיר את הארוחות של השגרה ולשים במקומן את הארוחות של New Me. אם אין – בוחרים כמה ארוחות ביום (2 ארוחות + נשנוש / 2 ארוחות + ארוחת ערב קלה / 2 ארוחות + נשנוש + ארוחת ערב קלה) ומתי כל אחת. ב\"2 ארוחות + נשנוש\" אלה ארוחת צהריים ב-11:30, נשנוש ב-16:00 וארוחת ערב ב-19:00 (אפשר לשנות כל אחת). אלה השעות של הארוחות בכל מקום: במסדרון, ב\"היום שלי\", ב\"השגרה שלי\" ובתזכורות. לא משנה כמה ארוחות – סך הקלוריות של היום נשאר: מה שירד מתחלק בין שאר הארוחות.",
    faq_q_new_me_times: "איך קובעים את שעות האוכל ב-New Me?",
