    nm_times_saved: "שעות האוכל נשמרו",
    nm_times_title: "שעות האוכל",
    faq_a_routine_exact_time: "כן. כשמתארים שגרה ל-AI עם שעה מדויקת (למשל \"16:10 מסחר\"), היא נשמרת בדיוק כך – בלי לעגל לשעה עגולה. מה שרשום בשגרה תמיד מופיע בלוח, גם אם השעה שלו לא נבחרה בהגדרות השעות, והסרה של שעה שיש בה משהו שואלת קודם. אפשר גם לשנות שעה ביד: נגיעה בשעה בחלון של הפריט, ובוחרים שעה ודקות.",
