    routine_hour_remove_text: "מה שרשום בשעה הזו יימחק מהשגרה: {title}",
    routine_hour_remove_title: "להסיר את {time}?",
    faq_a_routine_ai: "ב\"השגרה שלי\" פותחים את ⚙️ (או ➕) ונוגעים ב\"שגרה חדשה עם AI\": כותבים במילים פשוטות מה השגרה – למשל \"קימה ב-7, ספורט ב-8, עבודה עד 17\" – וה-AI בונה טאב חדש עם השעות והפריטים. אם כתוב לאילו ימים (\"בימי חול\"), הטאב נפתח בימים האלה, ושגרות שונות לימים שונים הופכות לטאבים נפרדים. אפשר לערוך הכול אחר כך כרגיל.",
    faq_a_routine_daysoff: "ב\"השגרה שלי\" נוגעים ב-➕ ואז ב\"ימי חופש\": בוחרים אילו ימים (למשל שישי ושבת) ומה השגרה בהם – בלי לו״ז (נשאר נקי), שגרה משלך, או לספר ל-AI מה עושים והוא יבנה אותה. ימי החופש מקבלים טאב משלהם, ובימים האלה \"השגרה שלי\" ו\"היום שלי\" מראים רק אותו.",
