    faq_a_secret_room_diary: "רק לך. דפי היומן נשמרים בחשבון, כך שהם שם בכל מכשיר, ואף אחד אחר לא רואה אותם. היומן הקסום שעל השולחן בחדר הסודי פותח אותו, וגם היומן שבפינת המוזיקה. מתחת לדף החדש יש לוח חודשי מקופל: נקודה מסמנת כל יום שיש בו דף, ונגיעה ביום פותחת את הדפים שלו – שם אפשר גם למחוק דף. כשהיומן כבר פתוח, אפשר גם להוסיף אותו לתפריט הראשי – במתג שביומן עצמו או בהגדרות של New Me.",
    faq_a_secret_room_places: "כל כניסה בשער היער נפתחת במפתח משלה. מאחוריהן: המרפסת מול הים (על השולחן הקטן מנורת אלאדין – נגיעה, ורוח היער יוצאת ממנה בערפל קסום, מסתובבת ומתחילה שיחה על המשאלה שלך – ר׳ ״מה עושה רוח היער מהמנורה?״), הגיטרה והיומן (הגיטרה מנגנת לחן קצר ורגוע ונעצרת לבד, וכל אחד משלושת התקליטים שתלויים בעץ מנגן לחן קסום משלו – נגיעה נוספת עוצרת – וביומן שעל הגדם כותבים), חדר הנשימה (אגם שקט בשקיעה – על המים צף פנס לוטוס: נוגעים בו, כותבים משאלה, והוא מתרחק איתה לאט אל תוך האגם; ועם שרביט הקסמים אפשר לכתוב בחול מה רוצים לשחרר, וזה נשאר עד שמוחקים באצבע) והשביל ביער (הוא נפתח בלילה, ונגיעה בפנסים מחליפה ליום; על הספסל אפשר לשבת, ונגיעה בשלט מקרבת אותו – לוח עם שש שאלות קטנות לסמן). בכניסה נעולה רואים כמה מפתחות נשארו. בסוף השביל, שער זוהר מוביל ליוגה ליד המפל – ומשם אל המפל עצמו.",
    faq_q_secret_room_diary: "מי רואה את היומן?",
