    ai_chat_working_table: "רגע, בונים את הטבלה…",
    faq_a_ai_chat: "לוחצים על הבועה ונפתחת שיחה. אפשר לבחור מה לעשות – משהו ליומן, מה אכלתי, תמונה של מתכון או טבלה חדשה – או פשוט לכתוב, והעוזר מזהה לבד. אפשר גם לגעת ב-🎙️ ולדבר במקום להקליד. ליומן אפשר לבחור פעם אחת, כל שבוע או כל יום. התשובה מגיעה בשיחה, ומשם אפשר להמשיך לעוד משהו או לפתוח את היומן / מה אכלתי.",
