    nm_tour_bag_title: "התיק הקסום",
    faq_a_new_me_routine_meals: "כשקובעים ארוחות ב-New Me ויש ארוחות גם ב״השגרה שלי״, New Me שואל אם להסתיר אותן ולשים במקומן את הארוחות של New Me – כדי ששום דבר לא יופיע פעמיים. אז בשגרה מופיעות הארוחות של New Me בשעות שלהן, עם 💎 ועם ✓; נגיעה בשם של ארוחה פותחת חלון לבחירת ארוחה אחרת או לשינוי השעה שלה, ישר שם מעל השגרה. כלום לא נמחק: אפשר להחזיר ב-⚙️ ההגדרות של New Me ← ארוחות בשגרה, או לכבות את \"סנכרון עם New Me\" ב-⚙️ של השגרה. בלי New Me פעיל, הן חוזרות לבד.",
