    nm_routine_text: "גם ב״השגרה שלי״ יש ארוחות. להסתיר אותן משם ולשים במקומן את הארוחות של New Me, כדי ששום דבר לא יופיע פעמיים?",
    nm_routine_title: "ארוחות גם בשגרה",
