    faq_a_dictation: "כן – לוחצים על המיקרופון 🎤 בפינת הפתק המהיר או עמוד כתיבה במחברת, ומדברים: המילים נכתבות תוך כדי, בשפת האפליקציה. לחיצה נוספת עוצרת. בפעם הראשונה הדפדפן מבקש הרשאה למיקרופון. עובד ב-Chrome / אנדרואיד ובספארי באייפון. במחשב צריך מיקרופון ודפדפן כמו Chrome, Edge או Safari – אם משהו חסר, ההודעה אומרת בדיוק מה.",
    faq_q_dictation: "אפשר לדבר במקום להקליד?",
    faq_a_secret_room: "חדר רק שלך, בתוך New Me – בית בתוך עץ ענק. רואים קיר אחד בכל פעם ומסתובבים עם החצים (או בהחלקה). המפתח הראשון מגיע אחרי ✓ על ארוחה ב-3 ימים שונים ופותח את הדלת – ואת כל החדר איתה: המחשב, המשחק, הפטיפון, המדף עם הספרייה שבתוכו והחתול. אחר כך כל אתגר שמסתיים (גם אתגר השבוע) נותן מפתח שפותח את המקום הבא: גג הכוכבים, המרפסת מול הים, הגיטרה והיומן, חדר הנשימה, השביל ביער עם היוגה, המפל והפתעה בגג – והאתגר ה-8 מביא בקבוק מהים, ובתוכו המכתב מהעבר. כשמשהו נפתח, חץ מראה את הדרך אליו. גם הדלתית שבתחתית מכונת המשחק נפתחת – בינתיים הארונית שמאחוריה ריקה. על גג הכוכבים, כוכב שנוגעים בו נופל ככוכב נופל, והחתול יושב על הכרית.",
