    room_wall_window_title: "החלון והמחשב",
    faq_a_steps_in_sport: "למעלה ב'מעקב אימונים', בפס קטן: הצעדים של היום ושל השבוע. הצעדים ייספרו לבד כשהאפליקציה תתחבר ל-Google Fit / Apple Health בגרסה לטלפון – כפתור ה-🔗 שלידם מסביר.",
    faq_q_steps_in_sport: "איפה מד הצעדים היומי?",
    sport_steps_today_label: "צעדים היום",
    sport_steps_week_label: "השבוע",
    faq_a_reminders_one_place: "כל תזכורת מגיעה פעם אחת, במקום אחד. כשהאפליקציה פתוחה מול העיניים (במחשב, באייפד או בטלפון) – היא מופיעה שם; אחרת היא מגיעה כהתראה לטלפון בלבד. '✅ בוצע, תודה!' או 'הבנתי!' בכל מקום סוגרים אותה בכל המכשירים, והיא לא חוזרת. 'עוד לא' דוחה אותה: היא חוזרת כל 5 דקות, בכל פעם במקום אחד. גם סימון ✓ על המשימה ברשימה נחשב 'בוצע'. כדי לקבל את ההתראות גם במחשב ובטאבלט, מדליקים את 'גם במחשב ובטאבלט' בהגדרות > התראות.",
    faq_q_reminders_one_place: "למה תזכורת מגיעה רק פעם אחת, ורק לטלפון?",
    reminder_all_devices_hint: "כברירת מחדל כל תזכורת מגיעה פעם אחת, במקום אחד: לטלפון, או למכשיר שבו האפליקציה פתוחה מול העיניים. 'בוצע' או 'הבנתי' במקום אחד סוגרים אותה בכל המקומות.",
    reminder_all_devices_label: "גם במחשב ובטאבלט",
    dev_weather_preview_label: "תצוגה מקדימה – רק בחשבון שלך:",
    myday_water_info: "8 כוסות מים בינוניות / קטנות הן בממוצע כ-2 ליטר",
    faq_a_good_things: "בערב (מ-18:00) מופיע מתחת לתאריך כפתור קטן: כותבים עד 3 דברים טובים שקרו היום – גם דבר אחד מספיק. הם נשמרים, וב'ימים קודמים' אפשר לראות מה נכתב קודם. 'לא הערב' מסתיר אותו עד מחר, ואפשר לכבות אותו לגמרי בהגדרות > התאמה אישית ויומן.",
    faq_a_home_countdown: "מסמנים אירוע ב-⭐ ביומן (הכוכב שלידו ברשימת האירועים). האירוע המסומן הקרוב ביותר ב-100 הימים הבאים מופיע מתחת לתאריך – 'עוד 3 ימים · יום הולדת לאמא', 'מחר · …' או 'היום · …'. לחיצה עליו קופצת ליום הזה ביומן.",
    faq_a_home_streak: "זה סופר כמה ימים ברצף היה לפחות ✓ אחד – כל דבר ב'היום שלי', ב'השגרה שלי', ב'היעדים שלי' או ב-New Me. הוא מופיע מ-2 ימים. כשעוד אין ✓ היום, הרצף לא נשבר – יש עוד את כל היום. ואם הרצף נגמר, הוא פשוט נעלם בשקט, בלי רגשות אשם.",
    faq_a_home_weather: "מפעילים את 'מזג אוויר בשמיים של מסך הבית' בהגדרות > התאמה אישית ויומן ומאשרים מיקום. אז השמיים של מסך הבית מראים את מזג האוויר האמיתי במקום – שמש (ובלילה ירח וכוכבים), עננים, גשם, שלג, סערה או ערפל – בכל ערכת צבע, ומתעדכנים בערך כל 40 דקות. המיקום המשוער (מעוגל לכקילומטר) נשאר רק במכשיר ונבדק דרך השרת שלנו מול MET Norway. כברירת מחדל זה כבוי. מתחת למתג כתוב מה יש עכשיו בחוץ – למשל ⛅ מעונן חלקית, ולכן בשמיים יש גם שמש וגם עננים.",
    faq_q_good_things: "מה זה \"3 דברים טובים מהיום\"?",
