    settings_good_things_label: "\"3 דברים טובים\" בערב",
    settings_weather_hint: "גשם, עננים או שלג ברקע של מסך הבית, לפי מזג האוויר במקום. המיקום המשוער נשאר במכשיר הזה ונבדק דרך השרת שלנו מול MET Norway.",
    settings_weather_label: "מזג אוויר בשמיים של מסך הבית",
    weather_failed: "לא הצלחנו לבדוק את מזג האוויר כרגע.",
    weather_location_denied: "אין גישה למיקום – אפשר לאשר אותה בהגדרות הדפדפן ולנסות שוב.",
    faq_a_home_focus: "לוחצים על ◎ בראש מסך הבית: הכול נעלם חוץ מהדבר האחד של עכשיו – מה שקורה בשעה הזו, או הדבר הבא ברשימה של היום – עם ✓ גדול, ופתק מהיר. אחרי ✓ מופיע הדבר הבא. 'מצב פוקוס ✕' למעלה מחזיר את הכול.",
    faq_a_home_search: "פותחים את התפריט ☰ – החיפוש נמצא ממש למעלה. מקלידים לפחות 2 אותיות: התוצאות מגיעות מהפתקים, מרשימת הקניות, מהיומן, מהמתכונים, מהמחברות (שמות וטקסט בדפים), מהיעדים, מהטבלאות ומהספרים, מסודרות לפי סוג – לחיצה על תוצאה קופצת ישר אליה.",
    faq_a_my_day: "'היום שלי' מחבר את מה שהיה 'הצצה להיום' ואת 'השגרה שלי' לציר זמן אחד. בתחתית מסך הבית רואים כמה כבר בוצע, מה עכשיו או הבא בתור (עם ✓ מהיר), וליד הכותרת – כוס מים בלחיצה. לחיצה (או החלקה למעלה) פותחת את כל היום: למעלה מה שאין לו שעה, ואחר כך הכול לפי השעות – משימות, אירועים ופגישות מהיומן, משבצות קבועות, השגרה של היום, הצעדים הקטנים של היעדים וארוחות New Me – עם קו של עכשיו. אפשר לסנן משימות, שגרה או פגישות ואירועים. ✓ כאן הוא אותו ✓ בכל מקום (השגרה שלי, היעדים שלי, היומן) ופותח חיננית בפינה. 'לערוך את השגרה' פותח את 'השגרה שלי' (שנמצאת גם בתפריט), ו'＋ להוסיף להיום' מוסיף משימה להיום. נגיעה בכותרת \"היום שלי\" (או בפס הקטן שלמעלה) סוגרת אותו שוב.",
