    reminder_closed_app_hint: "📱 כשהאפליקציה סגורה מושמע צליל ההתראות של הטלפון עצמו – אפשר להגביר אותו בהגדרות ההתראות של הטלפון לאפליקציה או לדפדפן (צליל, ו'הצגה קופצת על המסך').",
