    faq_a_new_me_letter_gift: "בתחילת New Me (או אחר כך, במסך האתגרים) אפשר לכתוב מכתב לעצמך בעתיד. אחרי החתימה אי אפשר לקרוא או לערוך אותו עד שהוא נפתח: בבקבוק מהים בחדר הסודי, או בסוף כל 20 האתגרים – ושם מחכה גם מתנה.",
    faq_q_new_me_letter_gift: "מה זה המכתב מהעבר?",
    faq_a_new_me_challenges: "ב-🏆 אתגרים יש 20 אתגרים: 10 גדולים (למשל 5 ימים בלי סוכר, שבוע בלי פחמימות, או לרדת 4 ק״ג בחודש – גירעון קלורי, אימון ובלי סוכר כל יום) ו-10 מיני – הרגלים קטנים לשבוע, כמו קפה עם קינמון בלי סוכר. בבחירת אתגר נשאל מתי מתחילים: היום, מחר, בשבוע הבא או בתאריך אחר. אתגר גדול ומיני-אתגר יכולים לרוץ במקביל. אתגר פעיל מופיע בראש התפריט וב'היום שלי', עם ✓ ליום. על כל שבוע באתגר יש יום חופשי אחד (🍕) שלא שובר אותו, ויום שלא סומן נחשב יום חופשי – אפשר לסמן את היום וגם את אתמול. חלק מהימים מסומנים לבד: אימון של 20 דקות במעקב האימונים, או הארוחות שבתפריט עם ✓. לכל אתגר יש ⓘ עם מה בדיוק נחשב (למשל הרשימה המלאה של הפחמימות) – באתגר עצמו וגם לידו ב'היום שלי'. מתחתיהם, ב-🌱 התפתחות אישית, יש 48 אתגרים קטנים לשבוע (הם לא נספרים ב-20) – ר׳ ״מה זה אתגר השבוע?״.",
