    faq_a_workout_calories: "כן. לכל אימון מחושבת הערכה של הקלוריות שנשרפו – לפי סוג האימון, משכו והמשקל האחרון (בריצה ובאופניים גם לפי המהירות, כשמוזן מרחק). היא מופיעה ברשימת האימונים ובסיכום החודשי (שריפה), ונוספת לתקציב הקלוריות של אותו יום: במעקב הארוחות היומי, במדדי קלוריות ומשקל ובטבעת של New Me. זו הערכה, ולכן היא מוצגת עם ~.",
    faq_q_workout_calories: "האימונים נכנסים לקלוריות של היום?",
    faq_a_new_me_flexible_menu: "כן. בשאלון ובהגדרות בוחרים כמה ארוחות ביום – 2 ארוחות + נשנוש / 2 ארוחות + ארוחת ערב קלה / 2 ארוחות + נשנוש + ארוחת ערב קלה – ו-➖ בכרטיס של ארוחה מסיר אותה (לפחות 3 נשארות); '➕ החזרה לתפריט' מחזיר אותה. בכל מקרה סך הקלוריות של היום נשאר: מה שירד מתחלק בין שאר הארוחות, ומתחת לכל ארוחה כתוב כמה נוסף לה ומה אפשר להוסיף. '✏️ לערוך' בארוחה פותח את הטקסט שלה – משנים מה שרוצים (למשל בלי לחם או עם עוד ביצה) וה-AI מחשב מחדש את הקלוריות והחלבון. 🔄 החלפה מציעה אפשרויות מהתפריט, ⭐ ארוחות קבועות ו-✨ כתיבה ל-AI; כל שינוי יכול להיות רק להיום או מעכשיו קבוע. ובסוף 'כל היום' יש '➕ להוסיף אוכל' – כותבים מה נאכל מחוץ לתפריט, וה-AI מחשב ומוסיף להיום (✕ מוחק).",
