    faq_a_app_tour: "הסיור נפתח אוטומטית פעם אחת, בכניסה הראשונה. הוא מתחיל בחלקים שלו – נגיעה בחלק קופצת ישר אליו – ואז מראה את כל חלקי האפליקציה (מסך הבית, עוזר ה-AI וכל פריט בתפריט) ואת חמש הקבוצות של ההגדרות, כל אחד עם הסבר קצר, ומציץ גם פנימה (למשל שביל יעד לדוגמה, התיק ויומן Google). 'המשך' מתקדם, 'חזרה' חוזר, 'לדלג על החלק הזה' קופץ לחלק הבא ו-✕ סוגר את הסיור. אפשר לראות אותו שוב בכל רגע בהגדרות > עזרה ושימוש > סיור באפליקציה, ולהמשיך מהמקום שבו נעצר. 'המשך' ו'חזרה' תמיד באותו מקום בתחתית המסך, ובמחשב אפשר גם עם החצים במקלדת.",
