    apptour_m_myweek_text: "לוח חודשי, משימות שבועיות קבועות עם תזכורות, כל האירועים שיש להם תאריך, ויומן נייר של הפגישות בשבוע 🤝.",
    apptour_m_newme_link: "הכול נספר במעקב הארוחות היומי וב'היום שלי'; המשקל משותף עם מדדי קלוריות ומשקל.",
    apptour_m_newme_text: "תוכנית תפריט של 1,300 / 1,500 קלוריות בתוך עולם משחק קסום: התפריט של היום עם ✓, החלפות בשלוש דרכים – מהתפריט, מהארוחות הקבועות, או בכתיבה ל-AI מה אכלת והוא מחשב את הקלוריות – רשימת קניות, תזכורות לארוחות ומסע התקדמות עם הישגים, מדידות ותמונות. ועוד 🏆 20 אתגרים – עם מתנה בסוף – ואתגר שבועי.",
    apptour_ai_table_text: "מתארים את הטבלה שצריך – וה-AI מתכנן את העמודות (פרימיום).",
    apptour_ai_photo_link: "נשמר ב'המתכונים שלי'.",
    apptour_ai_photo_text: "מצלמים מתכון כתוב – וה-AI ממלא מתכון חדש.",
    apptour_ai_schedule_link: "הן מופיעות ביומן וב'היום שלי'.",
    apptour_ai_schedule_text: "מתארים תוכניות במילים פשוטות, חד-פעמיות או קבועות – והן נכנסות ישר ליומן.",
    apptour_ai_food_link: "נכנס ישר למעקב הארוחות היומי ולסכום של היום.",
    apptour_ai_food_text: "כותבים מה נאכל – הקלוריות מחושבות ונרשמות לבד.",
    apptour_newme_short_text: "פותח את New Me – התפריט של היום נמצא ישר במסך הראשי.",
    apptour_ai_link: "תג קטן 1 עליו הוא התזכורת היומית 'מה חשוב היום'.",
    apptour_ai_text: "כותבים במילים פשוטות – והעוזר עושה את השאר: רושם קלוריות, מכניס תוכניות ליומן, קורא מתכון מתמונה ובונה טבלאות.",
    apptour_quicknote_link: "📝 ו-🛒 פותחים את הרשימות המלאות; 🍎 רושם ארוחה שמורה במעקב הארוחות היומי.",
    apptour_quicknote_text: "כותבים משהו מהר – לפתקים או ישר לרשימת הקניות.",
    apptour_routine_link: "הרגל יכול לרשום אימון במעקב האימונים אוטומטית.",
    apptour_routine_text: "השגרה היומית לפי שעות, בטאבים (ילדים, לימודים, עבודה…). מסמנים ✓ כל יום לבניית הרגלים ורצפים; 📅 מציג את כל החודש.",
    apptour_premium_text: "פותח את עוזר ה-AI המלא, ערכות נושא, גופנים, התיק שלי ועוד.",
    apptour_note_text: "פתק דביק לכל השבוע. בפנים, גלגל השיניים ⚙ מוסיף רשימה לסימון של 1–3 שורות ומשנה צבע וסגנון.",
    apptour_peek_link: "משימות מה-AI, מהיומן, מצעדים ביעדים ומגוגל קלנדר מופיעות כאן – וגם הקלוריות של היום 🔥 ויעד החודש 🎯.",
    apptour_peek_text: "כל מה שקורה היום במקום אחד – משימות, פגישות, השגרה והצעדים הקטנים בציר זמן אחד. מסמנים ✓ ישר מכאן.",
    apptour_date_text: "לחיצה עליו פותחת מבט מהיר ביומן החודשי – ואפשר להוסיף משהו מיד.",
