    table_select_option_delete_title: "מחיקת אפשרות",
    faq_a_other_manual_option: "בכל מקום שבו בוחרים מתוך רשימת אפשרויות יש גם '✏️ אחר' – בוחרים בו ומקלידים בדיוק את מה שצריך. בטבלה עם עמודת בחירה (למשל 'קרבה' בטבלת מתנות) לוחצים על התא, בוחרים '✏️ אחר', מקלידים את הערך (למשל 'אחיין') ולוחצים הוספה – הוא נשמר כאפשרות חדשה של אותה עמודה, כך שבפעם הבאה הוא כבר מופיע ברשימה. ה-× הקטן ליד כל אפשרות ברשימה הזו מוחק את האפשרות מהעמודה. בבחירת אייקון לטבלה יש הרבה אייקונים לבחירה, כולל פתקים צבעוניים. זה עובד באותה צורה בקטגוריות של ארוחות שמורות, בקטגוריות של מתכונים, בקטגוריות של הוצאות קבועות (נשמר כקטגוריה אישית חדשה) ובקטגוריות של היעדים.",
