    nm_drinks_hint: "מספיק לכתוב את שם המשקה – הקלוריות מחושבות אוטומטית, ואפשר לשנות את המספר.",
    nm_slot_drinks: "שתייה",
    faq_a_new_me_tracking: "נוגעים במשימה הבאה שבראש New Me ואז ב-✓ אכלתי כדי לסמן שהארוחה הבאה נאכלה – התפריט המלא עם ✓ על כל ארוחה נמצא ב'כל היום' שבצד, והארוחות של היום מופיעות גם ב'היום שלי' במסך הבית – נגיעה בארוחה שם (או מעבר עכבר מעליה) מראה בדיוק מה אוכלים, עם ✓ והחלפה. הכול מסונכרן עם מעקב הארוחות היומי: ארוחות התוכנית, השתייה וכל מה שנוסף במקום אחר (למשל קפה מההוספה המהירה) נספרים יחד ב-New Me וב'היום שלי' – שום דבר שכבר הוקלד לא נדרס, והסרת ✓ מסירה רק את החלק של New Me. כשכל הארוחות של היום מסומנות יש חגיגה קטנה. תחת 'שתייה' מוסיפים את המשקאות של היום – כולם יחד עד כ-150 קלוריות, כלומר בערך 3 משקאות של עד כ-50 קלוריות כל אחד. מספיק לכתוב את שם המשקה והקלוריות מתמלאות אוטומטית בעזרת AI. בשתי שורות הקפה/תה יש גם שדה 'חלב? כמה?' (למשל 'קצת' או '50 מ״ל'), והחישוב מתעדכן; אפשר לשנות את המספר לפני ההוספה וגם אחריה. משקה עם שם וקלוריות נשמר אוטומטית ברגע שעוברים הלאה – לא חובה ללחוץ על הוספה. לחיצה על ☆ ליד משקה שומרת אותו כמשקה קבוע – המשקאות הקבועים מופיעים ככפתורים בראש כרטיס השתייה, ולחיצה אחת מוסיפה אותם ליום. ⭐ שומר ארוחה כארוחה שמורה. 'טבלה יומית' מציגה מה נאכל עם קלוריות וחלבון. ה-💎 הקטן ליד מצב הפוקוס בראש מסך הבית פותח אותו ישירות. ערכי הקלוריות והחלבון הם הערכות AI ועלולים לכלול טעויות. לא אכלתי הכל? מתחת לארוחה מסומנת, ״לא אכלתי הכל?״ מוריד רבע, חצי או שלושה רבעים מהמנה – או את מה שכותבים, בחישוב – והקלוריות של היום מתעדכנות.",
    faq_q_new_me_tracking: "איך עובדים הסימון ✓, ההחלפות והקלוריות ב-New Me?",
    faq_a_new_me_what: "New Me היא תוכנית תפריט יומי נפרדת עם שתי תוכניות מוכנות – 1,300 או 1,500 קלוריות – שבנויות מ-2 ארוחות גדולות ו-2 נשנושים, עם 3 אפשרויות לכל אחת. היא כוללת את כל הפרימיום. המחיר: $11.99 לחודש (ביטול בכל רגע) או $99.99 פעם אחת לכל החיים. פותחים אותה מ-💎 New Me בתפריט. לפני ההתחלה יש שאלון קצר שנפתח בהצהרה רפואית שצריך לאשר. התוכנית היא מידע כללי בלבד ואינה מחליפה רופא/ה או דיאטן/ית קליני/ת.",
