    nm_disclaimer_p4: "4. הגבלת אחריות. השימוש בתוכנית הוא באחריות המשתמש/ת בלבד. מפתחי ומפעילי האפליקציה לא יישאו באחריות לכל נזק, ישיר או עקיף, בריאותי או אחר, הנובע מהשימוש בתוכנית, בתפריטים או בערכי הקלוריות והחלבון המוצגים, שהם הערכות משוערות בלבד.",
    nm_disclaimer_p3: "3. ללא אישור רפואי, התוכנית אינה מיועדת: לנשים בהריון או מניקות, לקטינים וקטינות מתחת לגיל 18, למי שמתמודד/ת או התמודד/ה בעבר עם הפרעת אכילה, למי שיש לו/ה מחלה כרונית או מחלת רקע (לרבות סוכרת, מחלות לב, כליות או כבד), או למי שנוטל/ת תרופות באופן קבוע – אלא באישור מפורש של רופא/ה מטפל/ת.",
    nm_disclaimer_p2: "2. בחירת התוכנית. הבחירה בין תוכנית של 1,300 קלוריות לתוכנית של 1,500 קלוריות נעשית על פי שיקול הדעת והאחריות הבלעדיים של המשתמש/ת. מומלץ להתייעץ עם רופא/ה או עם דיאטן/ית קליני/ת לפני תחילת כל דיאטה מוגבלת קלוריות.",
    nm_disclaimer_p1: "1. מידע כללי בלבד. תוכנית New Me והתפריטים הכלולים בה מספקים מידע תזונתי כללי בלבד ואינם מהווים ייעוץ רפואי, דיאטני או מקצועי אחר. אין בהם תחליף להתייעצות, לאבחון או לטיפול של רופא/ה או של דיאטן/ית קליני/ת מוסמך/ת. יש להתייעץ עם רופא/ה לפני כל שינוי תזונתי או תחילת פעילות גופנית.",
