    faq_q_daily_focus_prompt: "מה זו התזכורת הקטנה ששואלת מה הכי חשוב לי לעשות היום?", faq_a_daily_focus_prompt: "זו תזכורת יומית לפרימיום: פעם ביום מופיע תג \"1\" קטן על אייקון עוזר ה-AI. לחיצה על התג פותחת בועה ששואלת מה הכי חשוב לך לעשות היום, ומיד מוצגות בה 5 הצעות מוכנות (הן מתחלפות כל יום, ועוברות במהלך השנה בין נושאים שונים כדי שתמיד יהיה חדש) ועוד 'אחר' לכתיבה חופשית – אפשר לבחור יותר מאחת. לוחצים 'הוספה', והבחירות מופיעות כתגיות תזכורת קטנות בראש 'היום שלי' (הן לא משימות לסימון). סגירה עם ✕ או לחיצה מחוץ לבועה רק מעמעמת את התג לשאר היום, בלי להעלים אותו. היא דלוקה כברירת מחדל, ואפשר לכבות אותה בהגדרות > התאמה אישית ויומן. לא מתאים היום? לוחצים '🌙 לא היום' – התג נעלם עד מחר, ואז השאלה חוזרת כרגיל. אחת ההצעות מגיעה מהחיים שלך – הצעד הבא ביעד של החודש או הקריאה של היום. כל יום מתחילים מחדש.",
