    settings_notifications_label: "התראות תזכורות", settings_notifications_btn_enable: "🔔 הפעלה", settings_notifications_btn_enabled: "🔔 מופעל", settings_notifications_btn_blocked: "🔕 חסום", settings_reminder_chime_label: "צליל תזכורת", reminder_chime_preview_title: "השמעת הצליל הזה", reminder_chime_chord_up: "אקורד עולה", reminder_chime_bell: "פעמון", reminder_chime_soft_pop: "פופ רך", reminder_chime_marimba: "מרימבה", reminder_chime_alert: "התראה", reminder_chime_wind_chime: "פעמוני רוח",
    settings_notifications_status_default: "כדאי להפעיל כדי שתזכורות יתריעו גם כשהאפליקציה סגורה.", settings_notifications_status_granted: "מופעל – תזכורות יתריעו גם כשהאפליקציה סגורה.", settings_notifications_status_denied: "ההתראות חסומות לאפליקציה הזו בהגדרות הדפדפן/הטלפון. אפשר לפתוח הגדרות > התראות (או הגדרות האתר בדפדפן) ולאשר התראות ל-NOT10.ai, ואז לפתוח את האפליקציה מחדש.", settings_notifications_status_unsupported: "הדפדפן הזה לא תומך בהתראות ברקע.", settings_notifications_status_muted: "מושתק – תזכורות לא יתריעו, למרות שההתראות מאושרות.",
